//! Dialogue pipeline asset loader and source contract.
//!
//! The packet is generated by the extraction pipeline from MAIN.EXE
//! instruction words, the name tables and six real scene strings. This module
//! admits only that reviewed shape: every source control is accounted for, the
//! pacing rows and default are the source rows, the name mapping keeps code /
//! name index / portrait index separate, and every scene command names a valid
//! text, box and branch target.
//!
//! Nothing here derives art, audio, an atlas or a native frame. The packet is
//! logical contract plus text bytes; media acceptance stays a user gate.

const std = @import("std");
const validation = @import("validation");

pub const schema = "suikoden-dialogue-pipeline/1";
pub const pack = "combat-dialogue";

pub const MainExe = struct {
    file: []const u8,
    lba: u32,
    size: u32,
    header: u16,
    base: []const u8,
    body_sha256: []const u8,
};

pub const Slus = struct {
    file: []const u8,
    lba: u32,
    size: u32,
    header: u16,
    image_sha256: []const u8,
};

pub const Source = struct { main_exe: MainExe, slus: Slus };

pub const PacingRow = struct {
