pub const Pipeline = struct {
    schema: []const u8,
    pack: []const u8,
    source: Source,
    asserted_instructions: u16,
    pacing: Pacing,
    controls: []const Control,
    unsupported: []const Unsupported,
    grid: GridSpec,
    page: PageSpec,
    reveal: RevealSpec,
    queue: QueueSpec,
    names: Names,
    images: Images,
    choices: Choices,
    box: BoxSpec,
    speaker: SpeakerSpec,
    substitutions: Substitutions,
    scenes: []const Scene,
    corpus_corrections: []const Correction,

    pub fn scene(self: *const Pipeline, id: []const u8) ?*const Scene {
        for (self.scenes) |*entry| if (std.mem.eql(u8, entry.id, id)) return entry;
        return null;
    }

    pub fn sceneIndex(self: *const Pipeline, id: []const u8) ?u8 {
        for (self.scenes, 0..) |entry, index| if (std.mem.eql(u8, entry.id, id)) return @intCast(index);
        return null;
    }

    pub fn control(self: *const Pipeline, code: u8) ?*const Control {
        for (self.controls) |*entry| if (entry.code == code) return entry;
        return null;
    }

    pub fn variant(self: *const Pipeline, code: u8) ?*const SpeakerVariant {
        for (self.speaker.variants) |*entry| if (entry.code == code) return entry;
        return null;
    }

    /// Source 0x8013FA40/0x8013FB58: Hero (8) is skipped, 125+ is skipped,
    /// codes below 110 search the 109-byte list, and 110..124 use the code as
    /// the name index. Code 0 is a filler list slot and is refused rather than
    /// naming a non-speaker.
    pub fn nameIndex(self: *const Pipeline, code: u8) !?u8 {
        if (code == 0) return error.NullSpeakerCode;
        if (code == 8) return null;
        if (code >= self.names.skip_at_or_above) return null;
        if (code < 110) {
            for (self.names.characters) |character| {
                if (character.code == code and std.mem.eql(u8, character.source, "code_list")) return character.name_index;
            }
            return error.UnknownSpeakerCode;
        }
        for (self.names.characters) |character| {
            if (character.code == code and std.mem.eql(u8, character.source, "direct_rank")) return character.name_index;
        }
        return error.UnknownSpeakerCode;
    }

    pub fn characterForIndex(self: *const Pipeline, name_index: u8) ?*const Character {
        for (self.names.characters) |*character| if (character.name_index == name_index) return character;
        return null;
    }

    pub fn nameForCode(self: *const Pipeline, code: u8) !?[]const u8 {
        const index = try self.nameIndex(code) orelse return null;
        const character = self.characterForIndex(index) orelse return error.UnknownSpeakerCode;
        return character.name;
    }
};

pub fn commandKind(command: CommandSpec) !CommandKind {
    return std.meta.stringToEnum(CommandKind, command.kind) orelse error.UnsupportedCommand;
}

pub const CommandKind = enum {
    open_box,
    speaker,
    text,
    wait_confirm,
    close_box,
    wait_boxes,
    choice,
    branch_choice,
    jump,
    label,
    finish,
};

fn isHex(bytes: []const u8) bool {
    for (bytes) |byte| {
        if (!std.ascii.isHex(byte)) return false;
    }
    return true;
}

fn validId(id: []const u8) !void {
    if (!validation.isAsciiId(id, 64, "_-")) return error.InvalidId;
}

pub fn load(allocator: std.mem.Allocator, bytes: []const u8) !std.json.Parsed(Pipeline) {
    if (bytes.len > 512 * 1024) return error.AssetTooLarge;
    const parsed = try std.json.parseFromSlice(Pipeline, allocator, bytes, .{ .allocate = .alloc_always, .ignore_unknown_fields = true });
    errdefer parsed.deinit();
    try validate(parsed.value);
    return parsed;
}

fn validate(self: Pipeline) !void {
    if (!std.mem.eql(u8, self.schema, schema) or !std.mem.eql(u8, self.pack, pack)) return error.UnsupportedSchema;
    if (self.asserted_instructions < 64) return error.InvalidSource;
    if (self.source.main_exe.lba != 17976 or self.source.main_exe.header != 2048) return error.InvalidSource;
    if (self.source.main_exe.body_sha256.len != 64 or !isHex(self.source.main_exe.body_sha256)) return error.InvalidSource;

    // Pacing: exactly the three source rows and the selected normal row.
    if (self.pacing.rows.len != 3 or self.pacing.stride != 4) return error.InvalidPacing;
    for (self.pacing.rows, 0..) |row, index| {
        if (row.speed != index) return error.InvalidPacing;
        if (row.pressed > 5 or row.normal > 5) return error.InvalidPacing;
    }
    if (self.pacing.rows[0].pressed != 0 or self.pacing.rows[0].normal != 1) return error.InvalidPacing;
    if (self.pacing.rows[1].pressed != 1 or self.pacing.rows[1].normal != 3) return error.InvalidPacing;
    if (self.pacing.rows[2].pressed != 2 or self.pacing.rows[2].normal != 5) return error.InvalidPacing;
    if (self.pacing.default_setting != 1) return error.InvalidPacing;
    const selected = self.pacing.rows[self.pacing.default_setting];
    if (selected.normal != self.pacing.default_normal or selected.pressed != self.pacing.default_pressed) return error.InvalidPacing;
    if (!std.mem.eql(u8, self.pacing.default_name, selected.name)) return error.InvalidPacing;

    // Controls 1..16 are all present exactly once with the expected shape.
    var seen: [17]bool = @splat(false);
    for (self.controls) |entry| {
        if (entry.code == 0 or entry.code > 16) return error.InvalidControl;
        if (seen[entry.code]) return error.DuplicateControl;
        seen[entry.code] = true;
        const expected: u8 = switch (entry.code) {
            1, 2, 3, 15, 16 => 0,
            4, 5, 6, 8 => 1,
            7 => 2,
            else => 0,
        };
        if (entry.operands != expected) return error.InvalidControl;
    }
    var code: u8 = 1;
    while (code <= 16) : (code += 1) if (!seen[code]) return error.MissingControl;
    if (self.unsupported.len < 2) return error.InvalidControl;

    // Fixed-cell grid and source page/reveal masks.
    if (self.grid.columns != 30 or self.grid.rows != 5) return error.InvalidGrid;
    if (self.grid.cell_width != 8 or self.grid.cell_height != 12 or self.grid.blank_code != 0x10) return error.InvalidGrid;
    if (!std.mem.eql(u8, self.grid.mode, "fixed_cells")) return error.UnsupportedGrid;
    if (self.page.flag != 0x40 or self.page.ack_mask != 0x65) return error.InvalidPage;
    if (self.reveal.flag != 0x200 or self.reveal.mask != 0x65) return error.InvalidReveal;

    // Name table identity.
    const names = self.names;
    if (names.code_list_len != 109 or names.table_entries != 125 or names.pool_count != 125 or names.character_name_count != 124) return error.InvalidNames;
    if (names.portrait_index_max != 107 or names.skip_at_or_above != 125) return error.InvalidNames;
    if (names.skip_codes.len != 1 or names.skip_codes[0] != 8) return error.InvalidNames;
    if (names.pool.len != 125 or names.characters.len != 123) return error.InvalidNames;
    if (names.code_zero.code != 0 or names.code_zero.name_index == 0) return error.InvalidNames;
    var list_codes: [110]bool = @splat(false);
    var direct_codes: [15]bool = @splat(false);
    for (names.characters) |character| {
        if (character.name.len == 0 or character.name.len > 40) return error.InvalidNames;
        if (std.mem.eql(u8, character.source, "code_list")) {
            if (character.code > 109 or character.code == 8 or character.code == 0) return error.InvalidNames;
            if (list_codes[character.code]) return error.DuplicateName;
            list_codes[character.code] = true;
            if (character.portrait_index) |index| if (index != character.name_index or index > 107) return error.InvalidNames;
        } else if (std.mem.eql(u8, character.source, "direct_rank")) {
            if (character.code < 110 or character.code > 124) return error.InvalidNames;
            if (direct_codes[character.code - 110]) return error.DuplicateName;
            direct_codes[character.code - 110] = true;
            if (character.name_index != character.code) return error.InvalidNames;
            if (character.portrait_index != null) return error.InvalidNames;
        } else return error.InvalidNames;
    }
    var list_seen: usize = 0;
    code = 1;
    while (code <= 109) : (code += 1) {
        if (code == 8) continue;
        if (!list_codes[code]) return error.MissingName;
        list_seen += 1;
    }
    if (list_seen != 108) return error.InvalidNames;
    for (direct_codes) |present| if (!present) return error.MissingName;
    // The three identity anchors the port relies on.
    const kirkis = self.characterForIndex(23) orelse return error.InvalidNames;
    if (kirkis.code != 4 or !std.mem.eql(u8, kirkis.name, "Kirkis")) return error.InvalidNames;
    const viktor = self.characterForIndex(4) orelse return error.InvalidNames;
    if (viktor.code != 35 or !std.mem.eql(u8, viktor.name, "Viktor")) return error.InvalidNames;
    if ((try self.nameIndex(8)) != null or (try self.nameIndex(125)) != null) return error.InvalidNames;
    if ((self.nameForCode(110) catch null)) |name| {
        if (!std.mem.eql(u8, name, "Teo")) return error.InvalidNames;
    } else return error.InvalidNames;

    // Images, choices and box contract.
    const descriptor = self.images.descriptor;
    if (descriptor.width != 64 or descriptor.height != 64 or descriptor.bpp != 8 or descriptor.palette_entries != 256) return error.InvalidImages;
    if (self.images.branches.len != 2 or self.images.lookup_order.len != 2) return error.InvalidImages;
    const choices = self.choices;
    if (choices.mask != 0x5041 or choices.up != 0x1000 or choices.down != 0x4000) return error.InvalidChoices;
    if (choices.confirm.len != 2 or choices.confirm[0] != 0x40 or choices.confirm[1] != 0x01) return error.InvalidChoices;
    if (choices.operands.top != 1 or choices.operands.options != 2 or choices.operands.completion != 3) return error.InvalidChoices;
    if (choices.duration != 30 or choices.height.bit_clear != 1 or choices.height.bit_set != 2) return error.InvalidChoices;
    if (self.box.open_close_duration != 20 or !self.box.close_clears_image) return error.InvalidBox;

    // Speaker variants: every one must be internally consistent.
    var have_hero = false;
    var have_kirkis = false;
    var have_skip = false;
    for (self.speaker.variants) |variant| {
        if (variant.code == 8) have_hero = true;
        if (variant.code == 4) have_kirkis = true;
        if (variant.code == 125) have_skip = true;
        if (variant.skip_name) {
            if (variant.name != null or variant.prefix_updates != 0) return error.InvalidSpeaker;
        } else {
            const name = variant.name orelse return error.InvalidSpeaker;
            if (variant.prefix_updates != name.len + 1) return error.InvalidSpeaker;
        }
    }
    if (!have_hero or !have_kirkis or !have_skip) return error.InvalidSpeaker;

    if (self.substitutions.max_glyphs != 8) return error.InvalidSubstitutions;
    if (self.substitutions.player_name.len == 0 or self.substitutions.player_name.len > 8) return error.InvalidSubstitutions;
    if (self.substitutions.castle_name.len == 0 or self.substitutions.castle_name.len > 8) return error.InvalidSubstitutions;

    // Scenes: at least the six text scenes plus the choice scene.
    if (self.scenes.len < 7) return error.InvalidScenes;
    var saw_choice = false;
    var saw_hero_speaker = false;
    for (self.scenes) |scene| {
        try validId(scene.id);
        if (scene.texts.len == 0 or scene.texts.len > 4) return error.InvalidScenes;
        if (scene.commands.len == 0 or scene.commands.len > 64) return error.InvalidScenes;
        for (scene.texts) |text| {
            try validId(text.id);
            if (text.bytes_len == 0 or text.bytes_len > 0x385) return error.InvalidText;
            if (text.bytes_hex.len != @as(usize, text.bytes_len) * 2 or !isHex(text.bytes_hex)) return error.InvalidText;
            if (text.sha256.len != 64 or !isHex(text.sha256)) return error.InvalidText;
            if (text.pages.len == 0 or text.pages.len > 8) return error.InvalidText;
            if (text.widest_line > self.grid.columns) return error.InvalidText;
            for (text.pages) |page| {
                if (page.len > self.grid.rows) return error.InvalidText;
                for (page) |line| if (line.len > self.grid.columns) return error.InvalidText;
            }
        }
        var last_finish = false;
        for (scene.commands, 0..) |command, index| {
            const kind = try commandKind(command);
            if (command.box) |box| if (box >= 2) return error.InvalidCommand;
            if (command.text) |text| if (text >= scene.texts.len) return error.InvalidCommand;
            if (command.target) |target| if (target >= scene.commands.len) return error.InvalidCommand;
            switch (kind) {
                .open_box, .close_box => if (command.box == null) return error.InvalidCommand,
                .speaker => {
                    if (command.box == null or command.code == null) return error.InvalidCommand;
                    if (command.code.? == 0) return error.InvalidCommand;
                    if (command.code.? == 8) saw_hero_speaker = true;
                },
                .text => if (command.box == null or command.text == null) return error.InvalidCommand,
                .choice => {
                    saw_choice = true;
                    if (command.box == null or command.top == null or command.options == null or command.completion == null) return error.InvalidCommand;
                    if (command.options.? != 2) return error.InvalidCommand;
                    if (@as(u16, command.top.?) + command.options.? > self.grid.rows) return error.InvalidCommand;
                },
                .branch_choice => {
                    if (command.target == null or command.on == null) return error.InvalidCommand;
                    if (command.on.? > 1) return error.InvalidCommand;
                },
                .jump => if (command.target == null) return error.InvalidCommand,
                .wait_confirm, .wait_boxes, .label, .finish => {},
            }
            if (kind == .finish and index + 1 != scene.commands.len) return error.InvalidCommand;
            last_finish = kind == .finish;
        }
        if (!last_finish) return error.InvalidCommand;
    }
    if (!saw_choice or !saw_hero_speaker) return error.InvalidScenes;
    if (self.corpus_corrections.len != 4) return error.InvalidCorrections;
}
